-- The eleven sections of 2026-B with the professors of the identity seed (snapshot, no FK).
-- seats_available reflects the prototype's demo enrollments (kept by qone-enrollment-db); two
-- sections are full to demonstrate NO_SEATS. Upsert on the id.
ON CONFLICT (id) DO UPDATE SET subject_id = EXCLUDED.subject_id, term = EXCLUDED.term, group_number = EXCLUDED.group_number,
    professor_id = EXCLUDED.professor_id, professor_name = EXCLUDED.professor_name, capacity = EXCLUDED.capacity,
    seats_available = EXCLUDED.seats_available;
